"""Build a self-contained DOCX using standard-library Office Open XML."""
from datetime import datetime
from pathlib import Path
from xml.etree import ElementTree as ET
from xml.sax.saxutils import escape
from zipfile import ZipFile, ZIP_DEFLATED

ROOT = Path(__file__).resolve().parent.parent
OUTPUT = ROOT / "docs" / "Eurotherm_Reviewer_C_Drive_Storage_Explanation.docx"
W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
body = []


def p(text, style="Normal"):
    text = text.replace("\\\\", "\\")
    body.append(f'<w:p><w:pPr><w:pStyle w:val="{style}"/></w:pPr><w:r><w:t xml:space="preserve">{escape(text)}</w:t></w:r></w:p>')


def h(text):
    p(text, "Heading2")


def page(title, number):
    if body:
        body.append('<w:p><w:r><w:br w:type="page"/></w:r></w:p>')
    p(f"{number:02d}  /  TECHNICAL EXPLANATION", "Kicker")
    p(title, "Heading1")


def table(headers, rows, widths=None):
    widths = widths or [int(9900 / len(headers))] * len(headers)
    xml = ['<w:tbl><w:tblPr><w:tblW w:w="9900" w:type="dxa"/><w:tblBorders>']
    for edge in ("top", "left", "bottom", "right", "insideH", "insideV"):
        xml.append(f'<w:{edge} w:val="single" w:sz="4" w:color="D7E1EB"/>')
    xml.append('</w:tblBorders><w:tblCellMar><w:top w:w="70" w:type="dxa"/><w:left w:w="100" w:type="dxa"/><w:bottom w:w="70" w:type="dxa"/><w:right w:w="100" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>')
    xml += [f'<w:gridCol w:w="{width}"/>' for width in widths]
    xml.append('</w:tblGrid>')
    for i, row in enumerate([headers] + list(rows)):
        xml.append('<w:tr><w:trPr><w:cantSplit/>' + ('<w:tblHeader/>' if i == 0 else '') + '</w:trPr>')
        for value, width in zip(row, widths):
            shading = '<w:shd w:fill="17365D"/>' if i == 0 else '<w:shd w:fill="F3F6FA"/>' if i % 2 else ''
            run = '<w:b/><w:color w:val="FFFFFF"/>' if i == 0 else ''
            xml.append(f'<w:tc><w:tcPr><w:tcW w:w="{width}" w:type="dxa"/>{shading}</w:tcPr><w:p><w:pPr><w:pStyle w:val="TableText"/></w:pPr><w:r><w:rPr>{run}</w:rPr><w:t xml:space="preserve">{escape(str(value))}</w:t></w:r></w:p></w:tc>')
        xml.append('</w:tr>')
    xml.append('</w:tbl><w:p/>')
    body.append(''.join(xml))


