parts = {"[Content_Types].xml": types, "_rels/.rels": '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/></Relationships>', "word/document.xml": document, "word/styles.xml": styles, "word/_rels/document.xml.rels": rels, "word/header1.xml": header, "word/footer1.xml": footer, "docProps/core.xml": core}
OUTPUT.parent.mkdir(parents=True, exist_ok=True)
with ZipFile(OUTPUT, "w", ZIP_DEFLATED) as archive:
    for name, content in parts.items():
        ET.fromstring(content)
        archive.writestr(name, content.encode("utf-8"))
with ZipFile(OUTPUT) as archive:
    assert archive.testzip() is None
    xml = ET.fromstring(archive.read("word/document.xml"))
    text = " ".join(node.text or "" for node in xml.iter(f"{{{W}}}t"))
    assert len(list(xml.iter(f"{{{W}}}tbl"))) == 4
    assert len([node for node in xml.iter(f"{{{W}}}br") if node.get(f"{{{W}}}type") == "page"]) == 6
    assert "settings_MinFreeDiskSpace" in text and "187.19" in text
    print(f"Created: {OUTPUT}\nWords: {len(text.split())}\nPlanned pages: 7\nSize: {OUTPUT.stat().st_size} bytes\nOOXML package and XML checks: passed")
